SELECT ,
FROM sys_order o
o.is_deleted = 0
AND (o.order_no LIKE CONCAT('%', #{q.keyword}, '%') OR o.user_name LIKE CONCAT('%', #{q.keyword}, '%') OR o.mobile LIKE CONCAT('%', #{q.keyword}, '%') OR EXISTS (SELECT 1 FROM shop_order_item i WHERE i.order_id = o.id AND i.is_deleted = 0 AND (i.product_name LIKE CONCAT('%', #{q.keyword}, '%') OR i.spec_text LIKE CONCAT('%', #{q.keyword}, '%'))))
AND o.user_id = #{q.userId}
AND o.status = #{q.status}
AND EXISTS (SELECT 1 FROM shop_order_item i WHERE i.order_id = o.id AND i.is_deleted = 0 AND i.store_id = #{q.storeId})
AND EXISTS (SELECT 1 FROM shop_order_item i WHERE i.order_id = o.id AND i.is_deleted = 0 AND i.ship_status = #{q.shipStatus})
AND o.create_time >= #{q.beginTime}
AND o.create_time <= #{q.endTime}
ORDER BY o.id DESC

